------------------
---- MONITORS ----
------------------

-- monitors.lua is regenerated by nwg-displays on every GUI Apply (it writes
-- only the currently-connected heads). Portable entries for other
-- locations + the workspace-1 pin live in monitors-locations.lua so a
-- GUI save can never clobber them.
require("monitors")
