-------------------
---- AUTOSTART ----
-------------------

-- See https://wiki.hypr.land/0.56.0/Configuring/Basics/Autostart/
hl.on("hyprland.start", function()
  -- Lid-state check at compositor start: if the lid is ALREADY closed (cold
  -- boot or restart with lid down), no switch transition will fire, so the
  -- lid binds never trigger. Disable the internal panel explicitly here.
  -- Switch binds only fire on state TRANSITIONS (aquamarine emits toggle
  -- events on change only).
  local f = io.open("/proc/acpi/button/lid/LID1/state")
  if f then
    local state = f:read("*a")
    f:close()
    if state:find("closed") then
      -- Capture the panel's seat BEFORE disabling it: booting with the lid
      -- already closed fires no switch transition, so the lid-open path
      -- would otherwise fall back to a hardcoded seat. capturePanelSeat is
      -- defined in keybindings.lua, loaded before this callback runs.
      if capturePanelSeat then capturePanelSeat() end
      hl.monitor({ output = "eDP-1", disabled = true })
    end
  end
  hl.exec_cmd(terminal)
  hl.exec_cmd("quickshell")
  hl.exec_cmd("mullvad-daemon")
  hl.exec_cmd("udiskie --tray --notify")
  hl.exec_cmd("kdeconnectd")
  hl.exec_cmd("wl-paste --watch cliphist store")
  hl.exec_cmd("systemctl --user start hyprpolkitagent.service 2>/dev/null || hyprpolkitagent")
  -- Chrome debug instance for Hermes browser automation (CDP on port 9222)
  -- X11 + disable-vulkan: the debug instance crashes under Wayland+Vulkan
  -- Routed to workspace 7 via window rule below — never steals focus
  hl.exec_cmd(
    "google-chrome-stable --remote-debugging-port=9222 --user-data-dir=/home/nero/.config/google-chrome-debug --no-first-run --no-default-browser-check --ozone-platform=x11 --disable-vulkan --incognito --disable-extensions --disable-background-networking --disable-background-timer-throttling --disable-backgrounding-occluded-windows --disable-renderer-backgrounding"
  )
  hl.exec_cmd("openrgb -l; openrgb -p Brigth_Scar ")
end)

-- Quickshell bar: no blur layer rule.
-- A blur=true pass on the bar was a per-frame NVIDIA cost while the bar
-- was animating; the bar renders clean at full opacity without it and the
-- compositor skips the blur pass entirely on an idle desktop.

